  ["Penny"] = "Centavo",
  ["Penny "] = "Centavo",
  ["Peggy, George, I regret it."] = "Peggy, George, lamento.",
  ["Where on earth did Pells go? Isn't this her favorite place to come to?"] = "Para onde foi Pells? Este não é o lugar favorito dela para vir?",
  ["Payne (Daytime)"] = "Payne (diurno)",
  ["Equip"] = "Equipar",
  ["Equipped"] = "Equipado",
  ["The Distortion in the wearer's eyes bribes the truth of order."] = "A Distorção nos olhos do usuário suborna a verdade da ordem.",
  ["Pelageya"] = "Pelagia",
  ["Paisley "] = "Paisley",
