  ["Pretend to be Dunn"] = "Finja ser Dunn",
  ["Pretend to be Dunn 2"] = "Finja ser Dunn 2",
  ["Pretend to be Arnold"] = "Finja ser Arnold",
  ["Pretend to be a tall player"] = "Finja ser um jogador alto",
  ["Pretend nothing happened"] = "Finja que nada aconteceu",
